import React, { useState, useEffect } from 'react';
import api from '../utils/api';
import useAuth from '../hooks/useAuth';

const Dashboard = () => {
  const { user } = useAuth();
  const [events, setEvents] = useState([]);
  const [registrations, setRegistrations] = useState([]);
  const [certificates, setCertificates] = useState([]);

  useEffect(() => {
    if (user?.role === 'admin') {
      fetchAdminData();
    } else {
      fetchStudentData();
    }
  }, [user]);

  const fetchAdminData = async () => {
    try {
      const { data: eventsData } = await api.get('/events');
      setEvents(eventsData);
    } catch (error) {
      console.error('Failed to fetch events');
    }
  };

  const fetchStudentData = async () => {
    try {
      const { data: certData } = await api.get('/registrations/certificates');
      setCertificates(certData);
    } catch (error) {
      console.error('Failed to fetch certificates');
    }
  };

  if (!user) return <div>Please login</div>;

  return (
    <div className="container mx-auto py-8">
      <h1 className="text-3xl font-bold mb-8">Dashboard</h1>
      {user.role === 'admin' ? (
        <div>
          <h2 className="text-2xl font-bold mb-4">Manage Events</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {events.map((event) => (
              <div key={event._id} className="bg-white p-6 rounded-lg shadow-md">
                <h3 className="text-xl font-bold">{event.title}</h3>
                <p>{event.description}</p>
                <button className="mt-4 bg-blue-600 text-white px-4 py-2 rounded">Edit</button>
                <button className="mt-4 ml-4 bg-red-600 text-white px-4 py-2 rounded">Delete</button>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <div>
          <h2 className="text-2xl font-bold mb-4">My Certificates</h2>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {certificates.map((cert) => (
              <div key={cert._id} className="bg-white p-6 rounded-lg shadow-md">
                <p><strong>Type:</strong> {cert.type}</p>
                <p><strong>ID:</strong> {cert.certificateId}</p>
                <a href={`http://localhost:5000/${cert.filePath}`} target="_blank" rel="noopener noreferrer" className="mt-4 inline-block bg-blue-600 text-white px-4 py-2 rounded">Download</a>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default Dashboard;
